INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('verdad-y-traicion', 'Verdad Y Traición', 'verdad-y-traicion', 'B', 'DRAMA', 121, 'Cuando la lealtad a la patria se convierte en lealtad a una mentira, un adolescente lo arriesga todo para exponer la verdad. Con la Gestapo a la vuelta de la esquina, debe decidir qué significa realmente ser un buen alemán.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/21233/assets/Mexico/Tickets/Movies/VerdadYTraicion/Es/POSTER_720X1022_2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/21233/assets/Mexico/Tickets/Movies/VerdadYTraicion/Es/1440x900_55/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/21233/assets/Mexico/Tickets/Movies/VerdadYTraicion/Es/6a6a87cf65d5cverdadtraicion/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032357', 'Moana ', 'moana-live-action', 'A', 'MUSICAL, AVENTURA, FANTASÍA, ACCIÓN, FAMILIAR', 116, 'En la adaptación en acción real de Disney de la querida aventura animada nominada al Óscar®, Moana (Catherine Lagaʻaia) responde a la llamada del océano y, por primera vez, viaja más allá del arrecife de su isla de Motunui con el infame semidiós Maui (Dwayne Johnson) en un viaje inolvidable para devolver la prosperidad a su pueblo.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/19403/assets/Mexico/Tickets/Movies/MoanaLiveAction/Es/720x1022_24/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/19403/assets/Mexico/Tickets/Movies/MoanaLiveAction/Es/1440x900_57/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/19403/assets/Mexico/Tickets/Movies/MoanaLiveAction/Es/6a232a218be25MOANA2026_W8_1366x770_1/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032626', 'La Negociación', 'la-negociacion', 'B', 'SUSPENSO, CRIMEN', 106, 'En 1977. Tras ser estafado por un banco, Tony Kiritsis se presenta en sus oficinas y toma como rehén al hijo del presidente de la compañía, atándole al cuello un dispositivo mortal conectado al gatillo de una escopeta. Exige que le devuelvan su dinero, además de una disculpa pública que será retransmitida por televisión y vista por millones en prime time. Esta es la historia real de un crimen que conmocionó a toda una nación.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/20537/assets/Mexico/Tickets/Movies/LaNegociacion/Es/P_ster_720x1022px_2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/20537/assets/Mexico/Tickets/Movies/LaNegociacion/Es/Header_Movie_details_1440x900px_2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/20537/assets/Mexico/Tickets/Movies/LaNegociacion/Es/6a57c7b29e43flanegociacion/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('la-invitacion', 'La Invitación', 'la-invitacion', 'B15', 'COMEDIA', 107, 'Joe y Angela están en la cuerda floja, y esta noche podría ser el momento en que todo se desmorone definitivamente. Por desgracia, sus vecinos de arriba están a punto de llegar para cenar, y todo lo que puede salir mal está destinado a terminar mucho peor.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/19230/assets/Mexico/Tickets/Movies/LaInvitacion/Es/sello_720x1022_2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/19230/assets/Mexico/Tickets/Movies/LaInvitacion/Es/LI_DESKTOP_Header_flujo_de_compra_1440x900px_2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/19230/assets/Mexico/Tickets/Movies/LaInvitacion/Es/6a19e49b7727dinvitacion/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('impacto-mortal', 'Impacto Mortal', 'impacto-mortal', 'B', 'SUSPENSO', 107, 'Un vuelo de Los Ángeles a Shanghái sufre una falla catastrófica y termina en un aterrizaje forzoso en medio del océano. Los sobrevivientes quedan atrapados entre los restos del avión, mientras una manada de tiburones, atraída por el caos, comienza a rodearlos. Con el tiempo en contra y el fuselaje hundiéndose, deberán enfrentarse a sus peores miedos y tomar una decisión imposible: arriesgarlo todo en el mar… o morir dentro del avión.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/19935/assets/Mexico/Tickets/Movies/ImpactoMortal/Es/Poster_720x1022_DW_2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/19935/assets/Mexico/Tickets/Movies/ImpactoMortal/Es/Header_Movie_Details_1440x900_DW_2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/19935/assets/Mexico/Tickets/Movies/ImpactoMortal/Es/6a3af82a14495impactomortal/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('evil-dead-en-llamas', 'Evil Dead: En Llamas', 'evil-dead-en-llamas', 'C', 'TERROR', 110, 'Evil Dead: En Llamas desata el viaje más salvaje y aterrador de la franquicia hasta la fecha, irrumpiendo en la gran pantalla con un capítulo totalmente nuevo de carnicería y caos demoníaco. Tras la pérdida de su marido, una mujer busca consuelo con sus suegros en su aislada casa familiar. A medida que, uno a uno, se van transformando en Deadites —convirtiendo el encuentro en una reunión familiar del infierno—, ella descubre que los votos que hizo en vida... perduran incluso en la muerte.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/19297/assets/Mexico/Tickets/Movies/EvilDeadEnLlamas/Es/EVILDEAD_720x1022_2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/19297/assets/Mexico/Tickets/Movies/EvilDeadEnLlamas/Es/EVILDEAD_1440x900_2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/19297/assets/Mexico/Tickets/Movies/EvilDeadEnLlamas/Es/6a205679ed534l1_evildeadburn_itrb_sever_red_premium_w8_lasmx_sub_h264_770p_1/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('backrooms-sin-salida-version-extendida', 'Backrooms: Sin Salida Versión Extendida', 'backrooms-sin-salida-version-extendida', 'B15', 'TERROR', 127, 'Una extraña puerta aparece en el sótano de una tienda de muebles. Cuando el paciente de una terapeuta desaparece en una dimensión más allá de la realidad, ella deberá adentrarse en lo desconocido para intentar salvarlo. Adaptación de un cortometraje del propio Kane Parsons.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/20519/assets/Mexico/Tickets/Movies/BackroomsSinSalidaVersionExtendida/Es/720x1022_21/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/20519/assets/Mexico/Tickets/Movies/BackroomsSinSalidaVersionExtendida/Es/Header_movie_details_1440x900__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/20519/assets/Mexico/Tickets/Movies/BackroomsSinSalidaVersionExtendida/Es/6a5661ab454d2backrooms/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032496', 'PAW Patrol: La Dino Película', 'paw-patrol-la-dino-pelicula', 'AA', 'ANIMACIÓN, FAMILIAR', 89, 'Después de que su barco queda atrapado en una tormenta misteriosa, los cachorros de PAW Patrol se estrellan en una isla tropical desconocida llena de dinosaurios. Allí conocen a Rex, un cachorro que ha estado varado en la isla por años y que se ha convertido en un experto en todo lo relacionado con dinos. Cuando su archirrival, el Alcalde Humdinger, comienza a minar la isla de manera imprudente para explotar sus recursos naturales, provoca accidentalmente la erupción de un enorme volcán dormido. Los cachorros deberán enfrentarse a rescates gigantescos, más grandes que cualquier cosa que hayan enfrentado antes, para detener a Humdinger antes de que todo en la isla se extinga.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/19797/assets/Mexico/Tickets/Movies/PAWPatrolLaDinoPelicula/Es/PP3_Desktop_Poster_720x1022_2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/19797/assets/Mexico/Tickets/Movies/PAWPatrolLaDinoPelicula/Es/1440x900_55/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/19797/assets/Mexico/Tickets/Movies/PAWPatrolLaDinoPelicula/Es/6a343cd3ed50fpaw_patrol/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('pelicula-sorpresa', 'Película Sorpresa', 'pelicula-sorpresa', 'B15', 'COMEDIA, TERROR, ACCIÓN', 150, '¿Te atreves a ir a una función de cine sin saber qué película verás? Anímate a ser de los primeros en disfrutar de esta experiencia, con una película, que no te diremos cuál es, pero que nuestro equipo seleccionó cuidadosamente y que estamos seguros de que te gustará. Te invitamos a las nuevas Funciones Sorpresa de Cinépolis, diseñadas para salir de la rutina, sorprenderte y emocionarte. ¿Estás listo? ¿Será una película de terror, de comedia o de acción? Sólo una cosa es segura: Será una experiencia como ninguna otra.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/21412/assets/Mexico/Tickets/Movies/PeliculaSorpresa/Es/720x1022_definitiva_2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/21412/assets/Mexico/Tickets/Movies/PeliculaSorpresa/Es/1440x900_55/resource.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('marsupilami-caos-a-bordo', 'MARSUPILAMI: CAOS A BORDO', 'marsupilami-caos-a-bordo', 'A', 'COMEDIA', 98, 'Sinopsis: Para salvar su empleo en el zoológico, David acepta un plan arriesgado: debe traer de vuelta un paquete misterioso desde América del Sur. Termina en un crucero con su ex, su hijo y su torpe y no muy inteligente compañero Stéphane, a quien David utiliza para transportar el paquete en secreto. Todo sale mal cuando Stéphane abre accidentalmente el paquete y libera a un adorable bebé Marsupilami. Esta criatura rara y valiosa transforma rápidamente el viaje en un caos total. En medio de esta alocada aventura, David y su familia redescubren la fuerza de sus lazos familiares.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/21122/assets/Mexico/Tickets/Movies/MARSUPILAMICAOSABORDO/Es/Poster_WEB_Desktop_720x1022px_7__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/21122/assets/Mexico/Tickets/Movies/MARSUPILAMICAOSABORDO/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_8__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/21122/assets/Mexico/Tickets/Movies/MARSUPILAMICAOSABORDO/Es/6a68fb4ee1551ciclolynch/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032668', 'ERASERHEAD', 'eraserhead', 'B15', 'TERROR', 89, '“Un sueño de cosas oscuras y perturbadoras.” David Lynch', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/20895/assets/Mexico/Tickets/Movies/ERASERHEAD/Es/Poster_WEB_Desktop_720x1022px_4__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/20895/assets/Mexico/Tickets/Movies/ERASERHEAD/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_4__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/20895/assets/Mexico/Tickets/Movies/ERASERHEAD/Es/6a68e138b409bciclolynch/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('twin-peaks', 'TWIN PEAKS', 'twin-peaks', 'C', 'THRILLER', 50, 'Un pueblito tranquilo enclavado en un valle. Población: 51.201 habitantes. Una muerte misteriosa y una investigación que parece una farsa. Un diario secreto, un pacto, un yo maligno y un anillo. Sueños, alucinaciones, presentimientos. Historias de amor fugaces, una cantante que destila recuerdos de tiempos pasados. ¿Una habitación roja, líneas blancas y un hombre que acaba quemando su vida? Este es el mundo de TWIN PEAKS: FUEGO, CAMINA CONMIGO.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/20898/assets/Mexico/Tickets/Movies/TWINPEAKS/Es/Poster_WEB_Desktop_720x1022px_5__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/20898/assets/Mexico/Tickets/Movies/TWINPEAKS/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_6__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/20898/assets/Mexico/Tickets/Movies/TWINPEAKS/Es/6a68fa0e2be58ciclolynch/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032603', 'Nimrods: Una Comedia De Green Day', 'nimrods-una-comedia-de-green-day', 'A', 'COMEDIA', 116, 'Cuando Tommy recibe una llamada en la que invitan a su banda a ser teloneros de Green Day en Nochevieja, no se da cuenta de que se trata de una elaborada broma de su hermano mayor, Wayne. Desesperado por creer que su vida está a punto de cambiar, Tommy roba el coche de Wayne y empieza a conducir con su banda desde Kansas City hasta Los Ángeles, decidido a llegar en tres días. Lo que sigue es un viaje por carretera desenfrenado y divertidísimo por Estados Unidos, inspirado en los primeros años de gira de Green Day en una furgoneta, mucho antes del lanzamiento de Dookie, el álbum que los catapultó a la fama.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/20482/assets/Mexico/Tickets/Movies/NimrodsAGreenDayComedy/Es/Poster_WEB_Desktop_720x1022px_1__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/20482/assets/Mexico/Tickets/Movies/NimrodsAGreenDayComedy/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_1__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/20482/assets/Mexico/Tickets/Movies/NimrodsAGreenDayComedy/Es/6a5e8bf654dc0nimrods/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032616', 'Katseye: Wild Hearts En Cines', 'katseye-wild-hearts-en-cines', 'A', 'DOCUMENTAL, CONCIERTO', 80, 'El grupo femenino internacional KATSEYE, dos veces nominado a los premios GRAMMY®, llega a los cines de todo el mundo con un estreno especial en salas antes del lanzamiento de su tercer EP, WILD. KATSEYE: WILD HEARTS es un viaje fascinante a la nueva y audaz etapa del grupo que rinde homenaje a los fans que la hicieron posible. Con material inédito, videos de fans de EYEKONS y entrevistas íntimas con los miembros del grupo, la película explora el fuerte vínculo que une a KATSEYE con su comunidad de fans de todo el mundo. KATSEYE: WILD HEARTS, una carta de amor a los EYEKONS que ayudaron a crear este movimiento, nos muestra por qué la historia de este grupo apenas está comenzando. Desde la intensa presión de Dream Academy hasta el éxito viral que las llevó a lo más alto de las listas, el público vivirá los momentos de gloria, los reveses, los sacrificios y los momentos decisivos que transformaron a KATSEYE en su camino hacia el estrellato pop mundial. Elogiado por medios como The New York Times, Vogue, Rolling Stone y Billboard, KATSEYE se ha ganado el reconocimiento por su incansable dedicación a su arte y sus electrizantes actuaciones en vivo. Como uno de los grupos emergentes más prometedores del pop a nivel mundial, el grupo sigue consolidando su posición como una fuerza global. Del mismo equipo que creó POP STAR ACADEMY de Netflix, KATSEYE: WILD HEARTS es una producción de Interscope Films y Boardwalk Pictures, en colaboración con HYBE X GEFFEN, y está dirigida por Nadia Hallgren.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/20475/assets/Mexico/Tickets/Movies/KatseyeWildHearts/Es/Poster_WEB_Desktop_720x1022px_1__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/20475/assets/Mexico/Tickets/Movies/KatseyeWildHearts/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_1__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/20475/assets/Mexico/Tickets/Movies/KatseyeWildHearts/Es/6a5e8bcdd4f40katseye/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032676', 'GHOST: 2 Big To Rig En Cines', 'ghost-2-big-to-ring-en-cines', 'A', 'CONCIERTO', 115, 'Grabado en vivo durante los dos conciertos con entradas agotadas que GHOST dio en la Ciudad de México el año pasado, 2 BIG TO RIG es el documento definitivo de la inolvidable GIRA MUNDIAL SKELETOUR, que se presentará en IMAX® en ciertas ubicaciones. Con las únicas tomas profesionales de Papa V Perpetua y su banda de Nameless Ghouls del SKELETOUR —sin celulares—, 2 BIG TO RIG te sumerge en el ritual en vivo de GHOST, con imágenes exclusivas detrás de cámaras y acceso al backstage. 2 BIG TO RIG nació para compartir la experiencia del SKELETOUR con los fans en los lugares donde no era posible llevar a cabo el espectáculo por razones logísticas, y es una carta de amor para todos los que han sido parte del ritual de GHOST. Grabado en película de 16 mm, GHOST nunca se ha visto ni sonado mejor, con un repaso a temas de los seis álbumes de la banda, incluido SKELETÁ, número uno a nivel mundial en 2025, así como éxitos que no están en los discos, como «Mary On A Cross», «Kiss the Go-Goat» y «The Future is a Foreign Land».', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/20875/assets/Mexico/Tickets/Movies/GHOST2BigToRing/Es/Poster_WEB_Desktop_720x1022px_3__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/20875/assets/Mexico/Tickets/Movies/GHOST2BigToRing/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_3__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/20875/assets/Mexico/Tickets/Movies/GHOST2BigToRing/Es/6a6905aa52b4dghost/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
