INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032735', '2026 CORTIS TOUR PUT YOUR PHONE DOWN EN VIVO', '2026-cortis-tour-put-your-phone-down-en-vivo', 'A', 'MUSICAL', 165, '2026 CORTIS TOUR PUT YOUR PHONE DOWN IN LA: LIVE VIEWING Se trata de CORTIS, el artista que marca tendencia y se mantiene firme en medio del fervor apasionado de sus fans de todo el mundo. Capturando tanto la madurez musical de su segundo miniálbum «GREENGREEN» como la emoción abrumadora de su primer aniversario desde su debut, llega la primera gira como solista de CORTIS: 2026 CORTIS TOUR . ¡No te pierdas la oportunidad de vivir el estreno de Cortis en el cine, con una actuación llena de energía que te hará dejar el celular a un lado y perderte en el momento, en la emisión en vivo! Prepárate para vivir, amar y respirar la experiencia del concierto, donde podrás dejarte llevar por la misma ola de emoción y sentir el pulso de la multitud a través de una pantalla gigante y un sonido atronador.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/21254/assets/Mexico/Tickets/Movies/2026CORTISTOURPUTYOURPHONEDOWN/Es/Poster_WEB_Desktop_720x1022px_11__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/21254/assets/Mexico/Tickets/Movies/2026CORTISTOURPUTYOURPHONEDOWN/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_12__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/21254/assets/Mexico/Tickets/Movies/2026CORTISTOURPUTYOURPHONEDOWN/Es/6a749f1105062cortis/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032658', 'Inland Empire', 'inland-empire', 'A', 'THRILLER', 172, 'La actriz Nikki (Laura Dern) participa en un nuevo filme, debido a que su esposo (Peter J. Lucas) es muy celoso, su co-estelar Devon (Justin Theroux) recibe la advertencia de no hacer ninguna escena romántica -- especialmente porque los personajes que interpretan viven un romance. Ambos personajes descubren que el proyecto es una nueva versión de un filme inconcluso en el que las estrellas fueron asesinadas.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/21161/assets/Mexico/Tickets/Movies/InlandEmpire/Es/Poster_WEB_Desktop_720x1022px_8__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/21161/assets/Mexico/Tickets/Movies/InlandEmpire/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_9__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/21161/assets/Mexico/Tickets/Movies/InlandEmpire/Es/6a68f4153806fciclolynch/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032660', 'Mulholland Drive', 'mulholland-empire', 'A', 'THRILLER', 145, 'Nadie crea pesadillas cinematográficas como David Lynch, y ''Mulholland Drive''... es una de las más intensas y aterradoras. [Chicago Tribune] "No solo tiene todo lo que buscas en una película de David Lynch, sino casi todo lo que buscas en CUALQUIER película." [L.A. Weekly] "Una de las pocas películas en las que las piezas no solo suman mucho más que el todo, sino que lo superan con una serie de fragmentos (en su mayoría) fascinantes." [New York Observer] "Emocionante y absurda. La película se siente completamente instintiva." [The Village Voice] "''Mulholland Drive'' hace que las películas vuelvan a cobrar vida." [Rolling Stone] "Pocos podrán resistirse a su embriagadora intriga y a las dos cautivadoras actuaciones principales de Naomi Watts y Laura Elena Harring." [Hollywood Reporter]', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/21163/assets/Mexico/Tickets/Movies/MulhollandDrive/Es/Poster_WEB_Desktop_720x1022px_9__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/21163/assets/Mexico/Tickets/Movies/MulhollandDrive/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_10__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/21163/assets/Mexico/Tickets/Movies/MulhollandDrive/Es/6a68e1c83b2e7ciclolynch/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032736', 'Katy Perry: The Lifetimes Tour - En Vivo', 'katy-perry-the-lifetimes-tour-en-vivo', 'A', 'MUSICAL', 132, 'Grabada en el icónico Accor Arena de París durante los conciertos con todas las entradas agotadas de la gira Lifetimes Tour en noviembre de 2025, Katy Perry: The Lifetimes Tour – Live From Paris captura uno de los mayores espectáculos en directo del pop en su mejor momento. Dirigida por el reconocido realizador de conciertos Paul Dugdale y filmada con más de 60 cámaras, la película ofrece una experiencia inmersiva que hace sentir al público como si estuviera en primera fila, mostrando toda la magnitud, la energía y el espectacular despliegue visual de la gira mundial de Katy Perry. Con un repertorio que recorre toda su trayectoria e incluye sus mayores éxitos, una puesta en escena impresionante, coreografías espectaculares y la energía del público en cada canción, la película muestra a Katy Perry en uno de los mejores momentos de su carrera. Desde los instantes más cercanos con sus fans hasta los himnos que hacen vibrar todo el recinto, cada escena está filmada con una calidad cinematográfica que transporta al espectador al centro de un concierto inolvidable. Más que una película de concierto, The Lifetimes Tour – Live From Paris es una celebración del vínculo especial entre Katy Perry y sus fans, y de la música que ha marcado a toda una generación. Emocionante, vibrante y llena de energía, es la oportunidad perfecta para disfrutar en la gran pantalla de una de las mayores estrellas del pop haciendo lo que mejor sabe hacer: conquistar el escenario.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/21300/assets/Mexico/Tickets/Movies/KatyPerryTheLifetimesTourEnVivo/Es/Poster_WEB_Desktop_720x1022px_2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/21300/assets/Mexico/Tickets/Movies/KatyPerryTheLifetimesTourEnVivo/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_5/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/21300/assets/Mexico/Tickets/Movies/KatyPerryTheLifetimesTourEnVivo/Es/6a749f3d87cfdkatyperry/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032698', 'LOS MEJORES AÑOS DE NUESTRA VIDA', 'los-mejores-anos-de-nuestra-vida', 'A', 'DOCUMENTAL', 108, 'LOS MEJORES AÑOS DE NUESTRA VIDA.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/21399/assets/Mexico/Tickets/Movies/LOSMEJORESANOSDENUESTRAVIDA/Es/Poster_WEB_Desktop_720x1022px_15__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/21399/assets/Mexico/Tickets/Movies/LOSMEJORESANOSDENUESTRAVIDA/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_16__2/resource.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032662', 'ELEPHANT MAN', 'elephant-man', 'A', 'DRAMA', 123, 'El hombre elefante (1980), dirigida por David Lynch, es un drama biográfico ambientado en el Londres victoriano que narra la trágica historia real de Joseph Merrick (llamado John en el filme), un hombre con severas deformidades físicas, explotado como un fenómeno de circo, y el Dr. Frederick Treves, quien busca devolverle su dignidad humana.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/21256/assets/Mexico/Tickets/Movies/ELEPHANTMAN/Es/Poster_WEB_Desktop_720x1022px_13__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/21256/assets/Mexico/Tickets/Movies/ELEPHANTMAN/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_14__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/21256/assets/Mexico/Tickets/Movies/ELEPHANTMAN/Es/6a749fcb97c2dciclolynch/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032664', 'THE STRAIGHT STORY', 'the-straight-story', 'A', 'THRILLER', 100, 'The Straight Story, 1999), dirigida por David Lynch, es una road movie entrañable basada en hechos reales. Narra el viaje de Alvin Straight, un anciano de 73 años con problemas de salud que, al enterarse de que su hermano ha sufrido un infarto, decide recorrer más de 400 km desde Iowa hasta Wisconsin en su cortacésped, buscando la reconciliación.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/21398/assets/Mexico/Tickets/Movies/THESTRAIGHTSTORY/Es/Poster_WEB_Desktop_720x1022px_14__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/21398/assets/Mexico/Tickets/Movies/THESTRAIGHTSTORY/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_15__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/21398/assets/Mexico/Tickets/Movies/THESTRAIGHTSTORY/Es/6a74a0488227fciclolynch/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032766', 'Linkin Park: Unshatter En Cines', 'linkin-park-unshatter-en-cines', 'A', 'DOCUMENTAL', 108, 'Unshatter es una película documental de la banda Linkin Park dirigida por Joe Hahn. Narra el regreso del grupo, su reconstrucción tras la muerte de Chester Bennington y los años fuera de los escenarios.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/21588/assets/Mexico/Tickets/Movies/LinkinParkUnshatterEnCines/Es/Poster_WEB_Desktop_720x1022px_19__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/21588/assets/Mexico/Tickets/Movies/LinkinParkUnshatterEnCines/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_20__2/resource.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('sexo-suenos-amor', 'Sueños (Amor, Sexo)', 'sexo-suenos-amor', 'B', 'ROMANCE, DRAMA', 111, 'Johanne es una chica que se enamora perdidamente de su profesora de francés, experimentando su primer amor intenso. Deseando preservar sus sentimientos, la joven documenta sus emociones y experiencias por escrito. Cuando su madre y su abuela leen lo que ha escrito, al principio reaccionan con sorpresa ante su contenido íntimo, pero pronto quedan cautivadas por sus cualidades literarias. Mientras debaten sobre la moralidad y las posibles consecuencias de publicar los escritos de Johanne, ésta navega por el contraste entre los ideales románticos y la realidad, sumergiéndose en un viaje a través de las intensas emociones del autodescubrimiento, el amor y la sexualidad.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/20534/assets/Mexico/Tickets/Movies/SexoSuenosAmor/Es/Suen_os_poster_720x1022_2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/20534/assets/Mexico/Tickets/Movies/SexoSuenosAmor/Es/Header_Movie_details_1440x900_1__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/20534/assets/Mexico/Tickets/Movies/SexoSuenosAmor/Es/6a57c65b47654sexosuenosamor/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('obsesion', 'Obsesión', 'obsesion', 'C', 'THRILLER, HORROR', 109, 'El anhelo romántico desesperado de un hombre por su amor platónico desencadena un hechizo siniestro en el perturbador debut de Curry Barker.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/17688/assets/Mexico/Tickets/Movies/Obesion/Es/20_POSTER_720X1022_2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/17688/assets/Mexico/Tickets/Movies/Obesion/Es/4_HEADER_MOVIE_DETAILS_1440X900_9/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/17688/assets/Mexico/Tickets/Movies/Obesion/Es/69dec5c3e11c6obsesion_3/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('el-dia-de-la-revelacion', 'El Día De La Revelación', 'el-dia-de-la-revelacion', 'B', 'CIENCIA FICCIÓN', 145, 'La historia sigue a varias personas que comienzan a experimentar fenómenos extraños cuando señales aparentemente inexplicables revelan la presencia de vida extraterrestre en la Tierra. A medida que estos eventos se vuelven globales, surge una verdad impactante que podría cambiar el destino de la humanidad: no estamos solos. Entre conspiraciones, secretos gubernamentales y conexiones personales con los alienígenas, el mundo entero se enfrenta al llamado “día de la revelación”, donde la verdad finalmente sale a la luz.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/18348/assets/Mexico/Tickets/Movies/ElDiaDeLaRevelacion/Es/20_Po_ster_720x1022px_1__11/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/18348/assets/Mexico/Tickets/Movies/ElDiaDeLaRevelacion/Es/15_Header_Movie_details_1440x900px_1__11/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/18348/assets/Mexico/Tickets/Movies/ElDiaDeLaRevelacion/Es/69fb5eed7a9eediarevelacion_2/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032670', 'LMD SOLO LAS MÁS 2', 'lmd-solo-la-mas-2', 'A', 'MEXICANA', 150, 'Transmisión en vivo de La Gran final de Solo Las Más 2. Después de una serie de desafíos donde las feminosas demostraron ser Las Más, llegamos al último capítulo donde se disputarán las finalistas el título de “La Máxima” totalmente en vivo conoceremos a la nueva reina de esta épica competencia.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/20832/assets/Mexico/Tickets/Movies/LMDSOLOLAMAS2/Es/Poster_WEB_Desktop_720x1022px_2__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/20832/assets/Mexico/Tickets/Movies/LMDSOLOLAMAS2/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_2__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/20832/assets/Mexico/Tickets/Movies/LMDSOLOLAMAS2/Es/6a68fe085efb5slm2/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032750', 'Puella Magi Madoka Mágica: La Película Parte 1', 'puella-magi-madoka-magica-la-pelicula', 'A', 'ANIMACIÓN', 130, '¡Descubre Madoka Mágica, el fenómeno que revolucionó el género de las chicas mágicas, en el cine! Madoka Kaname recibe de la misteriosa criatura Kyubey la oportunidad de cumplir cualquier deseo a cambio de convertirse en una chica mágica para combatir a las aterradoras brujas. Homura Akemi, una enigmática estudiante, hará todo lo posible por impedir que acepte el contrato. Vive en la pantalla grande el inicio de un ícono de la animación japonesa.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/21566/assets/Mexico/Tickets/Movies/PuellaMagiMadokaMagica/Es/Poster_WEB_Desktop_720x1022px_17__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/21566/assets/Mexico/Tickets/Movies/PuellaMagiMadokaMagica/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_18__2/resource.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032752', 'Puella Magi Madoka Magica: La Película Parte 2', 'puella-magi-madoka-magica-la-pelicula-2', 'A', 'ANIMACIÓN', 111, 'Emociónate con la segunda parte de Madoka Magica. Después del desgarrador final de la primer parte, en esta entrega Madoka descubre entre muchas cosas los orígenes de Kyubey. Mientras tanto, se revela la historia de Homura y la aterradora bruja Walpurgisnacht. Vive en pantalla grande la segunda película de Puella Magi Madoka Magica, el fenómeno que redefinió el género de las chicas mágicas.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/21571/assets/Mexico/Tickets/Movies/PuellaMagiMadokaMagica2/Es/Poster_WEB_Desktop_720x1022px_18__2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/21571/assets/Mexico/Tickets/Movies/PuellaMagiMadokaMagica2/Es/HeaderMovieDetails_WEB_Desktop_1440x900px_19__2/resource.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032490', 'Adolescencia, Sexo Y Muerte En Campamento Miasma', 'adolescencia-sexo-y-muerte-en-campamento-miasma', 'C', 'COMEDIA, TERROR', 112, 'Una joven y entusiasta directora debe resucitar la franquicia de Campamento Miasma tras años de secuelas mediocres. Pero cuando visita a la protagonista de la película original, una actriz recluida y envuelta en misterio, ambas se sumergen en un mundo empapado de sangre, deseo, miedo y delirio.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/19736/assets/Mexico/Tickets/Movies/AdolescenciaSexoYMuerteEnCampamentoMiasma/Es/720x1022_2/resource.JPG', 'https://tickets-static-content.cinepolis.com/pimcore/19736/assets/Mexico/Tickets/Movies/AdolescenciaSexoYMuerteEnCampamentoMiasma/Es/1440x900_55/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/19736/assets/Mexico/Tickets/Movies/AdolescenciaSexoYMuerteEnCampamentoMiasma/Es/6a32d84c95a13Campmiasma/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('HO00032629', 'Loco México Mágico', 'loco-mexico-magico', 'B15', 'COMEDIA', 105, 'En Alvarado, Veracruz, un ambicioso alcalde decide filmar una épica película estilo Hollywood para convertir al pueblo en un destino turístico internacional. Con un equipo improvisado, una estrella pop como protagonista y una misión para defender la identidad mexicana, nace una aventura tan caótica como entrañable: ¡Alvarado Espectacular!', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/20539/assets/Mexico/Tickets/Movies/LocoMexicoMagico/Es/LMM_DESKTOP_Poster_720x1022px_2/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/20539/assets/Mexico/Tickets/Movies/LocoMexicoMagico/Es/1440x900_55/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/20539/assets/Mexico/Tickets/Movies/LocoMexicoMagico/Es/6a57c8d76ebc1locomexicomagico/resource.mp4') ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
INSERT INTO PELICULA (vista_id, titulo, slug, clasificacion, genero, duracion_min, sinopsis, categoria, poster_url, banner_url, trailer_url) VALUES ('papa-a-cargo', 'Papá A Cargo', 'papa-a-cargo', 'A', 'COMEDIA', 99, 'Cuando una supermamá consigue un acuerdo en Shark Tank, intercambia roles con su esposo como el principal sostén económico de la familia. Ahora el lucha por adaptarse a su nueva vida como padre que se queda en casa cuidando a sus tres hijas.', 'Cartelera', 'https://tickets-static-content.cinepolis.com/pimcore/21510/assets/Mexico/Tickets/Movies/PapaACargo/Es/720x1022_24/resource.jpg', 'https://tickets-static-content.cinepolis.com/pimcore/21510/assets/Mexico/Tickets/Movies/PapaACargo/Es/1440x900_55/resource.jpg', NULL) ON CONFLICT (slug) DO UPDATE SET clasificacion = EXCLUDED.clasificacion, categoria = EXCLUDED.categoria, sinopsis = COALESCE(EXCLUDED.sinopsis, PELICULA.sinopsis), poster_url = COALESCE(EXCLUDED.poster_url, PELICULA.poster_url), banner_url = COALESCE(EXCLUDED.banner_url, PELICULA.banner_url), trailer_url = COALESCE(EXCLUDED.trailer_url, PELICULA.trailer_url);
